// Immediate termination (syscall wrapper), no C library cleanup.
// Skips stdio stream flushing, atexit handlers, and object destructors.
// Status is returned to parent process via wait() family calls.

#define E_FATAL_INIT 127

void initialize() {
    if (resource_missing) {
        _Exit(E_FATAL_INIT);
    }
}

pid_t pid = fork();
if (pid == 0) {
    initialize();
}
